<script>
(() => {
    const form = document.querySelector('[data-page-block-editor]');
    const inspector = form?.querySelector('[data-inspector]');
    if (!form || !inspector) return;

    const styleFields = [
        ['background_color', 'Background colour', 'color'],
        ['text_align', 'Text alignment', 'select'],
        ['padding', 'Padding', 'select'],
        ['margin_custom', 'Margin', 'text'],
        ['border_color', 'Border colour', 'color'],
        ['border_width', 'Border width', 'text'],
        ['border_radius', 'Corner radius', 'text'],
    ];
    const advancedFields = [
        ['desktop_visibility', 'Show on desktop', 'checkbox'],
        ['tablet_visibility', 'Show on tablet', 'checkbox'],
        ['mobile_visibility', 'Show on mobile', 'checkbox'],
        ['custom_class', 'Custom CSS class', 'text'],
    ];

    const esc = (value) => String(value ?? '').replace(/[&<>"']/g, (char) => ({
        '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;'
    }[char]));

    const fieldValue = (key, fallback = '') => {
        const blocks = window.oneMinistryPageEditor?.blocks || JSON.parse(form.dataset.blocks || '[]');
        const block = blocks[window.oneMinistryPageEditor?.selected ?? 0];
        return block?.data?.[key] ?? fallback;
    };

    const renderField = ([key, label, kind]) => {
        const value = fieldValue(key, key.includes('color') ? '#ffffff' : '');
        if (kind === 'color') {
            return `<label>${label}<input type="color" data-field="${key}" value="${esc(value)}"></label>`;
        }
        if (kind === 'checkbox') {
            const checked = value === '' || value === 'true' || value === true || value === 'yes';
            return `<label class="page-object-check"><input type="checkbox" data-field="${key}" value="true" ${checked ? 'checked' : ''}><span>${label}</span></label>`;
        }
        if (key === 'text_align') {
            return `<label>${label}<select data-field="${key}"><option value="left">Left</option><option value="center">Centre</option><option value="right">Right</option></select></label>`;
        }
        if (key === 'padding') {
            return `<label>${label}<select data-field="${key}"><option value="compact">Compact</option><option value="regular">Regular</option><option value="spacious">Spacious</option></select></label>`;
        }
        return `<label>${label}<input data-field="${key}" value="${esc(value)}" placeholder="Optional"></label>`;
    };

    const activate = (key, tabs) => {
        tabs.querySelectorAll('[data-object-tab]').forEach((button) => {
            const active = button.dataset.objectTab === key;
            button.classList.toggle('is-active', active);
            button.setAttribute('aria-selected', active ? 'true' : 'false');
        });
        tabs.parentElement.querySelectorAll('[data-object-panel]').forEach((panel) => {
            const active = panel.dataset.objectPanel === key;
            panel.hidden = !active;
            panel.classList.toggle('is-active', active);
        });
    };

    const enhance = () => {
        const selected = inspector.querySelector('.page-inspector-selected');
        if (!selected || inspector.querySelector('[data-object-tabs]')) return;
        const actions = inspector.querySelector('.page-inspector-actions');
        const content = document.createElement('section');
        content.className = 'page-object-tab-panel is-active';
        content.dataset.objectPanel = 'content';
        [...inspector.children].filter((node) => node !== actions && !node.matches('.page-inspector-selected')).forEach((node) => content.append(node));
        const style = document.createElement('section');
        style.className = 'page-object-tab-panel';
        style.dataset.objectPanel = 'style';
        style.hidden = true;
        style.innerHTML = `<div class="page-object-control-grid">${styleFields.map(renderField).join('')}</div>`;
        const advanced = document.createElement('section');
        advanced.className = 'page-object-tab-panel';
        advanced.dataset.objectPanel = 'advanced';
        advanced.hidden = true;
        advanced.innerHTML = `<div class="page-object-control-grid">${advancedFields.map(renderField).join('')}</div>`;
        const tabs = document.createElement('div');
        tabs.className = 'page-object-tabs';
        tabs.dataset.objectTabs = 'true';
        tabs.setAttribute('role', 'tablist');
        tabs.setAttribute('aria-label', 'Block settings');
        ['content', 'style', 'advanced'].forEach((key, index) => {
            const button = document.createElement('button');
            button.type = 'button';
            button.dataset.objectTab = key;
            button.setAttribute('role', 'tab');
            button.setAttribute('aria-selected', index === 0 ? 'true' : 'false');
            button.className = index === 0 ? 'is-active' : '';
            button.textContent = key[0].toUpperCase() + key.slice(1);
            button.addEventListener('click', (event) => {
                event.preventDefault();
                event.stopPropagation();
                activate(key, tabs);
            });
            tabs.append(button);
        });
        inspector.replaceChildren(selected, tabs, content, style, advanced);
        if (actions) inspector.append(actions);
        inspector.dataset.enhanced = 'true';
    };

    const observer = new MutationObserver(() => {
        if (!inspector.querySelector('[data-object-tabs]')) queueMicrotask(enhance);
    });
    observer.observe(inspector, { childList: true });
    enhance();
})();
</script>
</x-layouts.workspace>
